/*
 * Compatibility stand-in, not GSAP. Pages generated by earlier versions of
 * nr_landingpage load this file and run scripts stored in the page that use
 * GSAP. GSAP is no longer shipped (see Documentation/Usage).
 *
 * The contract is deliberately small:
 *
 * - Nothing throws. Every global the GSAP 3 files defined (gsap,
 *   ScrollTrigger, Observer, TextPlugin, TweenMax, TimelineMax, the ease
 *   objects, ...) is one inert value that can be read, assigned, called,
 *   constructed, iterated and awaited; `await` gives an inert value as well.
 * - The animation script the extension generated keeps its content: its
 *   typewriter empties a heading and then calls gsap.to(el, {text: ...}), so
 *   text is written back into elements that are empty at that moment, and
 *   full opacity (opacity or autoAlpha of 1) and a visibility other than
 *   hidden are applied. Text is never written over existing text, and no
 *   value that hides or dims content is applied.
 * - Nothing else: no animation, no other properties, and no callbacks of
 *   the page apart from promise continuations (`await`, `.then()`), which
 *   run as soon as the promise settles. Scripts that an LLM wrote in
 *   creative mode are not emulated; such pages need to be generated again.
 *
 * ScrollTrigger.min.js and TextPlugin.min.js only remain for the script tags
 * of those pages.
 */
(function () {
  'use strict';

  var inert;

  function isList(value) {
    return Array.isArray(value)
      || (typeof NodeList !== 'undefined' && value instanceof NodeList)
      || (typeof HTMLCollection !== 'undefined' && value instanceof HTMLCollection);
  }

  // As gsap.utils.toArray(): a selector gives its elements, a list its
  // entries, any other value a list with that value.
  function toArray(value) {
    if (typeof value === 'string') {
      return elements(value);
    }
    if (isList(value)) {
      return Array.prototype.slice.call(value);
    }
    return value ? [value] : [];
  }

  function elements(target) {
    var found = [];
    var collect = function (item, depth) {
      if (typeof item === 'string') {
        try {
          Array.prototype.push.apply(found, document.querySelectorAll(item));
        } catch (e) {
          // Not a selector, for example a media query.
        }
      } else if (item && item.nodeType === 1) {
        found.push(item);
      } else if (isList(item) && depth < 3) {
        Array.prototype.forEach.call(item, function (entry) { collect(entry, depth + 1); });
      }
    };
    collect(target, 0);
    return found;
  }

  function show(nodes, vars) {
    if (vars === null || typeof vars !== 'object') {
      return;
    }
    var text = vars.text;
    if (text !== null && typeof text === 'object') {
      text = text.value;
    }
    nodes.forEach(function (element) {
      if (typeof text === 'string' && text !== '' && element.textContent === '') {
        element.textContent = text;
      }
      if (Number(vars.autoAlpha) >= 1) {
        element.style.opacity = '1';
        element.style.visibility = 'visible';
      }
      if (Number(vars.opacity) >= 1) {
        element.style.opacity = '1';
      }
      if (typeof vars.visibility === 'string' && vars.visibility !== 'hidden') {
        element.style.visibility = vars.visibility;
      }
    });
  }

  function handle(args) {
    var nodes = elements(args[0]);
    for (var i = 1; i < args.length; i++) {
      show(nodes, args[i]);
    }
    return inert;
  }

  // While a promise settles with the inert value, it must not look
  // thenable, or the promise would follow it forever; GSAP clears `then`
  // on its tweens the same way.
  var resolving = false;

  function settle(resolve) {
    resolving = true;
    try {
      resolve(inert);
    } finally {
      resolving = false;
    }
  }

  inert = new Proxy(function () {}, {
    get: function (target, property) {
      if (property === 'then') {
        if (resolving) {
          return undefined;
        }
        return function (onFulfilled, onRejected) {
          return new Promise(settle).then(function (value) {
            if (typeof onFulfilled !== 'function') {
              return value;
            }
            // The continuation may be a promise's own resolve function,
            // which would read `then` again.
            resolving = true;
            try {
              return onFulfilled(value);
            } finally {
              resolving = false;
            }
          }, onRejected);
        };
      }
      if (property === 'toArray') {
        return toArray;
      }
      if (property === Symbol.toPrimitive) {
        return function () { return 0; };
      }
      return inert;
    },
    // The target's name and length are read-only; assigning them must
    // not throw in strict mode.
    set: function () { return true; },
    apply: function (target, self, args) {
      return handle(args);
    },
    construct: function (target, args) {
      handle(args);
      return inert;
    }
  });

  [
    'gsap', 'ScrollTrigger', 'Observer', 'TextPlugin', 'CSSPlugin', 'AttrPlugin', 'EndArrayPlugin',
    'ModifiersPlugin', 'RoundPropsPlugin', 'SnapPlugin', 'gsapVersions',
    'TweenLite', 'TweenMax', 'TimelineLite', 'TimelineMax',
    'Back', 'Bounce', 'Circ', 'Cubic', 'Elastic', 'Expo', 'Linear', 'Power0', 'Power1', 'Power2',
    'Power3', 'Power4', 'Quad', 'Quart', 'Quint', 'Sine', 'SteppedEase', 'Strong'
  ].forEach(function (name) {
    if (window[name] === undefined) {
      window[name] = inert;
    }
  });
})();
